let devlogActiveTab='all';
function devlogPhaseNo(x){const m=String(x?.phase||'').match(/P(\d+)/);return m?Number(m[1]):-1}
function devlogNewest(items){return [...items].sort((a,b)=>devlogPhaseNo(b)-devlogPhaseNo(a)||(String(b.date||'').localeCompare(String(a.date||''))))}
function devlogOldest(items){return [...items].sort((a,b)=>devlogPhaseNo(a)-devlogPhaseNo(b)||(String(a.date||'').localeCompare(String(b.date||''))))}
function devlogEventHeadingHTML(x){
 return `<div class="log-event-head"><div class="log-event-title"><span class="log-event-name">${esc(x.title)}</span>${x.date?`<span class="log-event-date">${esc(x.date)}</span>`:''}</div><span class="log-event-phase">${esc(x.phase)} · ${esc(x.version||'')}</span></div>`;
}
function devlogListHTML(items,type){
 return devlogNewest(items).map(x=>`<article class="log-event ${type}">
   ${devlogEventHeadingHTML(x)}
   ${x.bullets&&x.bullets.length?`<ul>${x.bullets.map(v=>`<li>${esc(v)}</li>`).join('')}</ul>`:''}
 </article>`).join('');
}
function devlogBugHTML(items){
 const badgeClass=s=>s.includes('用户')?'user':(s.includes('AI')||s.includes('开发自检'))?'ai':s.includes('未记录')?'history':'regression';
 return devlogNewest(items).map(x=>`<article class="log-event fix">
  ${devlogEventHeadingHTML(x)}
  <div class="log-event-meta">
   <span class="log-meta-chip ${badgeClass(x.found)}"><b>发现</b>${esc(x.found)}</span>
   <span class="log-meta-chip regression"><b>归因</b>${esc(x.origin)}</span>
   <span class="log-meta-chip"><b>状态</b>已修复</span>
  </div>
  <dl class="bug-detail">
   <dt>用户可见症状</dt><dd>${esc(x.symptom)}</dd>
   <dt>根因 / 判断</dt><dd>${esc(x.root)}</dd>
   <dt>修复方式</dt><dd>${esc(x.fix)}</dd>
   <dt>验证 / 回归</dt><dd>${esc(x.verify)}</dd>
  </dl>
 </article>`).join('');
}
function devlogTimelineHTML(items){
 return devlogNewest(items).map(x=>`<div class="timeline-item">
   <div class="tl-top"><span class="tl-phase">${esc(x.phase)}</span><span class="tl-date">${esc(x.date)}</span></div>
   <h4>${esc(x.title)}</h4><p>${esc(x.brief)}</p><span class="tl-metric">${esc(x.metric)}</span>
 </div>`).join('');
}
function devlogIntegrity(){
 const current=RELEASE_MANIFEST.phase||'P?';const v='网页 v'+RELEASE_MANIFEST.version;
 const phases=[...new Set(DEVLOG_TIMELINE.map(x=>Number(String(x.phase).replace('P',''))).filter(Number.isFinite))].sort((a,b)=>a-b),max=Number(String(current).replace('P',''));
 const missing=[];for(let n=0;n<=max;n++)if(!phases.includes(n))missing.push('P'+n);
 return{ok:!missing.length&&DEVLOG_FEATURES.some(x=>x.phase===current&&x.version===v)&&DEVLOG_INTERNALS.some(x=>x.phase===current&&x.version===v)&&DEVLOG_TIMELINE.some(x=>x.phase===current),missing,current,v}
}
function renderDevlogViews(){
 const range=$('#devlogRange');if(range)range.textContent=`AI提示词工作区 · 2026-09-11 21:43 → ${RELEASE_MANIFEST.date} · P0 – ${RELEASE_MANIFEST.phase} 全程记录`;
 const f=$('#devFeatureStream'),b=$('#devBugStream'),i=$('#devInternalStream'),t=$('#devTimeline'),all=$('#devAllDynamic');
 if(all){
   const phases=[...new Set([...DEVLOG_FEATURES,...DEVLOG_BUGS,...DEVLOG_INTERNALS,...DEVLOG_TIMELINE].map(x=>x.phase))].sort((a,b)=>devlogPhaseNo({phase:b})-devlogPhaseNo({phase:a}));
   all.innerHTML=phases.map(ph=>{
    const fs=DEVLOG_FEATURES.filter(x=>x.phase===ph),bs=DEVLOG_BUGS.filter(x=>x.phase===ph),ins=DEVLOG_INTERNALS.filter(x=>x.phase===ph),tl=DEVLOG_TIMELINE.find(x=>x.phase===ph),meta=fs[0]||ins[0]||bs[0]||tl||{};
    const date=meta.date||(tl?.date?('2026-'+tl.date):'');
    return `<section class="dev-recent-phase" data-dev-phase="${esc(ph)}"><h3><span class="vtag">${esc(ph)}</span>${esc(meta.version||tl?.title||meta.title||ph)} <span class="dev-phase-date">${esc(date)}</span></h3>${tl?`<p class="dev-phase-brief">${esc(tl.brief)}</p>`:''}${devlogListHTML(fs,'feature')}${devlogBugHTML(bs)}${devlogListHTML(ins,'internal')}</section>`
   }).join('');
 }

 if(f)f.innerHTML=devlogListHTML(DEVLOG_FEATURES,'feature');
 if(b)b.innerHTML=devlogBugHTML(DEVLOG_BUGS);
 if(i)i.innerHTML=devlogListHTML(DEVLOG_INTERNALS,'internal');
 if(t)t.innerHTML=devlogTimelineHTML(DEVLOG_TIMELINE);
 const integrity=devlogIntegrity(),di=$('#devlogIntegrity'),pc=$('#devPhaseCount'),pr=$('#devPhaseRange');
 if(di)di.innerHTML=`<b>${integrity.ok?'✓ 追溯完整':'⚠ 追溯缺口'}</b> · 当前 ${esc(integrity.v)} / ${esc(integrity.current)} · ${integrity.missing.length?'缺少 '+esc(integrity.missing.join('、')):'P0–'+esc(integrity.current)+' 时间线连续'} · 使用教程 / 开发日志 / 发布 同步`;
 if(pc)pc.textContent=DEVLOG_TIMELINE.length;if(pr)pr.textContent=`开发阶段 · P0–${integrity.current}`;
 const fc=$('#devFeatureCount'),bc=$('#devBugCount'),ic=$('#devInternalCount');
 if(fc)fc.textContent=DEVLOG_FEATURES.length;
 if(bc)bc.textContent=DEVLOG_BUGS.length;
 if(ic)ic.textContent=DEVLOG_INTERNALS.length;
}
function setDevlogTab(name,focus=false){
 const tabs=[...document.querySelectorAll('[data-devtab]')];
 const panels=[...document.querySelectorAll('[data-devpanel]')];
 const next=tabs.find(x=>x.dataset.devtab===name)||tabs[0];
 devlogActiveTab=next.dataset.devtab;
 tabs.forEach(btn=>{const on=btn===next;btn.setAttribute('aria-selected',on?'true':'false');btn.tabIndex=on?0:-1;});
 panels.forEach(p=>p.classList.toggle('active',p.dataset.devpanel===devlogActiveTab));
 const sc=$('#devlogScroller');if(sc)sc.scrollTop=0;
 if(focus)next.focus();
}
function initDevlogTabs(){
 renderDevlogViews();
 const tabs=[...document.querySelectorAll('[data-devtab]')];
 tabs.forEach((btn,idx)=>{
   btn.addEventListener('click',()=>setDevlogTab(btn.dataset.devtab));
   btn.addEventListener('keydown',e=>{
     let n=null;
     if(e.key==='ArrowRight')n=(idx+1)%tabs.length;
     else if(e.key==='ArrowLeft')n=(idx-1+tabs.length)%tabs.length;
     else if(e.key==='Home')n=0;
     else if(e.key==='End')n=tabs.length-1;
     if(n!==null){e.preventDefault();setDevlogTab(tabs[n].dataset.devtab,true);}
   });
 });
 setDevlogTab('all');
}

