DEVLOG_INTERNALS.push({phase:'P62',version:'网页 v6.40',date:'2026-10-08',title:'File Staging, Global Reading and Window Geometry',bullets:['文件导入先解析到暂存区，确认后一次写入；校验空文件、错误 JSON、重复 ID 与写入失败，原有记录和失败时的预览可保留。','全局阅读先还原原始显示样式，再计算倍率，避免嵌套文本累计放大；新渲染内容使用合并的更新通知。','最大化保存几何样式而不保存层级；还原时保留当前焦点和窗口层级，尺寸变化继续适配浏览器视口。',"教程、开发日志、源码与 发布版本清单 同步 v6.40 / P62。"]});
