DEVLOG_BUGS.push({phase:'P63',version:'网页 v6.41',title:'多窗口拖动被重复字体重算和布局写入拖慢',found:'用户反馈后代码路径复核',origin:'P62 全局阅读与旧窗口拖动路径集成回归',symptom:'打开多个窗口后拖动明显卡顿。',root:'聚焦的样式类变化触发全页面阅读字号重算；高频移动事件逐次写入 left/top，模板窗口另有一套重复移动逻辑。',fix:'只对真实开关状态更新阅读；已聚焦窗口不重复改层级。拖动统一按帧合并并用 transform 平移，结束后提交最终几何；交互期间延后阅读刷新并暂停背景绘制。',verify:'状态门禁模拟连续移动、最后坐标、取消、失去捕获、八方向边界与缩放；实际浏览器帧率未测，不把状态检查作为浏览器流畅度证据。'});
DEVLOG_INTERNALS.push({phase:'P63',version:'网页 v6.41',date:'2026-10-08',title:'Navigation Identity, Search Focus and Motion Scheduling',bullets:['按钮排序移动原 DOM 节点，保留事件监听和数量角标；旧备份默认使用标准顺序，失效 ID 会被过滤，新功能自动追加。','中文输入组合结束后检索；搜索框使用动态委托，不依赖已移除的导航输入框，主题重建保留查询值。','连续 pointermove 合并为每帧一次位置预览，pointerup 同步提交最后坐标；丢失捕获和离开窗口会清理交互状态。100% 阅读不计算全量字体，拖动期间的内容更新在结束后合并应用。',"教程、开发日志与 发布版本清单 同步 v6.41 / P63；交付 HTML 与源码重建核对字节一致。"]});
