DEVLOG_FEATURES.push({phase:'P64',version:'网页 v6.42',date:'2026-10-09',title:'全局帮助改为任务用途、操作结果与边界说明',bullets:['工作区全部 15 个日常与高级页签分别解释适合什么时候用、如何开始、结果和边界；使用帮助与页签弹出说明共用同一目录。','补齐随手记、来源广场、文件导入、需求匹配、模板页签、版本历史、策展、发布、审查和修复等动态控件的说明。明确本地规则、预演与真实状态变更的区别。',"点击时重新读取按钮状态，归档/恢复、正文/内容差异、收藏/取消收藏显示相应说明。帮助内可退出后继续操作，输入控件退出后恢复填写，禁用操作说明先决条件。"]});
DEVLOG_BUGS.push({phase:'P64',version:'网页 v6.42',title:'工作区与动态按钮帮助退回无意义的点击说明',found:'用户截图反馈后逐项核查帮助入口与操作处理器',origin:'全局帮助缺少工作区及治理动作的专用匹配，动态说明依赖渲染时的旧数据',symptom:'审计追溯等页签只显示点击执行对应操作，不能说明需求、用途或操作后果。',root:'帮助仅覆盖部分静态 ID 与模板控件，没有 data-pw-tab 和大量动态动作的映射；showHelp 优先读旧 dataset，状态变化后说明可能过时。',fix:'建立共用任务说明目录，覆盖 15 个工作区页签与实际动作；打开说明时重新解析目标，移除伪说明兜底。新增节点局部装饰与同步点击解析，避免观察器延迟漏拦截。',verify:'专用门禁逐项解析静态与模板生成控件，检查状态分支、帮助点击和表单提交不执行业务操作、禁用按钮先决条件、显式退出继续与局部观察器；真实浏览器视觉未测。'});
DEVLOG_INTERNALS.push({phase:'P64',version:'网页 v6.42',date:'2026-10-09',title:"Context Help 覆盖率 and Side-effect Boundaries",bullets:['审查实际处理器语义：整版回滚是计划登记，通道回滚是指针回退，正式发布是浏览器运行态，统一审查批准可能恢复编排；说明按这些边界书写。','帮助解析只读控件及固定目录，不调用治理计算或存储。观察器只处理新增节点；窗口正文更新不再反复扫描整页。','说明使用用途、怎么用与留意三个部分，文字区域可滚动；输入焦点、键盘提交、动态未装饰按钮与禁用动作均有针对性验证。','教程、日志、发布清单同步 v6.42 / P64；单独 HTML、ZIP 内成品与源码重新构建结果核对一致。']});
