DEVLOG_FEATURES.push({phase:'P66',version:'网页 v6.44',date:'2026-10-09',title:'模板窗口缩放、拖动与内容滚动分离',bullets:['桌面母模板与个人模板工作台可正常调整高度；拖动标题时保留已调整的宽高，不再跳回占满屏幕。四边四角缩放、最小尺寸和最大化还原继续可用。','长内容在模板窗口内部滚动，标题与关闭按钮留在外框；内容区域不再要求至少一屏高，滚动不带动旁边的窗口。','模板窗口首次打开也进入共享边界校正，较矮浏览器窗口保持标题和上下边框可见；手机保留整页查看方式。']});
DEVLOG_BUGS.push({phase:'P66',version:'网页 v6.44',date:'2026-10-09',title:'模板窗口缩小后又被撑满，拖动时跳到上缘',found:'用户实际操作反馈后核对 CSS 级联和共享拖动的测量路径',origin:'旧全屏工作台的最小高度遗留在桌面窗口中',symptom:'主页面打开模板后上下缩放困难，调整后再拖动会突然顶到屏幕上沿，看起来无法保留窗口大小。',root:'旧 .panel 的 min-height:100dvh 高于用户设置的小高度；拖动控制器再次读取被最小高度撑大的实际尺寸，视口边界校正只剩顶部可放。内部 .ws 也保留了至少一屏高的约束。',fix:'桌面模板外框改用与共享缩放一致的有限最小高度；正文区可收缩并独立滚动，移除内部工作台的全屏最小高度。模板窗口加入共享打开与视口边界观察，保留移动端原有全屏布局。',verify:'生产 CSS 级联检查及受实际 CSS 最小高度约束的几何模拟先复现旧错误，再覆盖六主题缩小后拖动、上边缩放、滚动位置、最大化还原、短视口初次打开和移动端守卫；真实浏览器视觉未测。'});
DEVLOG_INTERNALS.push({phase:'P66',version:'网页 v6.44',date:'2026-10-09',title:"Template Frame Minimum and CSS-aware Geometry 质量退步",bullets:['修复仅限定桌面模板外框；沿用按帧合并的拖动和八方向缩放，不修改模板、来源、个人记录或草稿结构。','正文滚动区使用可收缩的 flex 子项、滚动边界和稳定滚动槽；标题留在外框，材质纹理只覆盖外框，不随变换扩大到视口。','新增 CSS 约束回归：对六主题计算实际优先级，模拟旧 100dvh 限制下的缩小失效与拖动贴顶；修复后尺寸、位置、滚动状态和还原几何可保持。',"教程、开发日志和 发布 同步 v6.44 / P66；所有既有回归门禁与源码包独立重建一致性核对。"]});
DEVLOG_TIMELINE.push({phase:'P66',date:'10-09',title:'网页 v6.44',brief:'修复模板窗口缩放后拖动贴顶；长内容在外框内滚动，尺寸由窗口决定。',metric:'缩放不回弹 · 内部滚动 · 几何保持'});

DEVLOG_FEATURES.push({phase:'P67',version:'网页 v6.45',date:'2026-10-09',title:'离线 Excel 与多条提示词批量导入',bullets:['文件导入支持 XLSX、XLS、CSV、TSV、TXT、Markdown 和 JSON。单文件 20 MB、本批文件合计 40 MB、最多 10000 条；后台解析带进度和取消，不上传内容。','表格按工作表选择并映射正文、名称、分类、标签、署名发布者、出处和条目 ID；保留来源文件、工作表与原始行号。文本可整篇导入，或按明确分隔标记、Markdown 一级标题拆分。','每页 15 条预览，长正文按需展开，跨页保留勾选。正文重复和同名默认跳过，可逐条核对后导入为独立新记录；不覆盖已有内容。','个人提示词迁移到本地数据库，偏好与提示词分开存储；本批保存成功后才更新个人库。工作区备份继续使用原 JSON 格式，恢复等待数据库保存完成。']});
DEVLOG_BUGS.push({phase:'P67',version:'网页 v6.45',date:'2026-10-09',title:'旧导入无法读取大表格，整包存储限制批量增长',found:'用户提出多条文件、Excel 和超过 1 MB 的实际导入需求后审查存储路径',origin:'单条文本导入规则与整包 localStorage 保存方式沿用至批量场景',symptom:'Excel 无法上传，文本难以拆分，多条 JSON 全量渲染；大内容被 1 MB 上限拦截，增加记录后偏好修改仍重写全部提示词。',root:'旧解析仅支持文本和 JSON，缺少表格列映射与去重预览；个人记录和偏好一起 JSON 序列化同步写入 localStorage，容量和主线程开销不适合大批内容。',fix:'离线内嵌固定版 SheetJS，通过 Worker 解析表格和文本；有界分页预览与勾选，正文必选、无效行不能导入。个人记录与小核心分仓存入 IndexedDB，旧数据自动迁移并保留旧副本；批量交易完成后再更新运行态，失败保留预览与已有记录。',verify:'实际固定版 Excel 解析、CSV 引号和多行、文本边界、去重勾选、事务中止回滚、旧数据迁移和重载、备份恢复及既有门禁回归；详细执行范围和限制见本批验证报告。'});
DEVLOG_INTERNALS.push({phase:'P67',version:'网页 v6.45',date:'2026-10-09',title:'Worker Parsing, Transactional Personal Records and Compatible Boot',bullets:['固定 SheetJS CE 0.20.3 与 Apache-2.0 许可随源码和 HTML 离线打包；不执行单元格公式或宏。Excel 受文件大小、展开声明体积、行列与工作表数量限制，超限明确提示分批，不静默截断。','异步启动先读取数据库再初始化应用；旧统一工作区和旧散列键迁移后保留原副本。数据库读取失败且已有迁移标记时停止启动，避免回退空状态覆盖旧数据。','偏好和草稿只写小核心；提示词独立对象仓。交易按请求回调分批入队，确认导入与备份恢复等待完成；导入保存期间个人编辑暂缓，其他窗口继续查看。','分页摘要和按需全文避免批量挂载长正文；读取取消与换文件使用令牌保护，旧读取结果不能覆盖新选择。保存状态、失败提示和离页提示可见。',"教程、帮助、开发日志与 发布 同步 v6.45 / P67；工作区 JSON schema 保持 v6，源码和交付 HTML 独立重建核对。"]});
DEVLOG_TIMELINE.push({phase:'P67',date:'10-09',title:'网页 v6.45',brief:'离线表格与多条文本导入、列映射、分页去重预览，个人数据迁移到数据库。',metric:'20 MB 文件 · 15 条预览 · 事务保存'});

DEVLOG_BUGS.push({phase:'P67',version:'网页 v6.45',date:'2026-10-09',title:"个人提示词 从回收站恢复后重复出现",found:'批量写入边界检查时追踪恢复入口和共用新增函数',origin:'恢复入口和新增函数各自向个人记录数组添加一次',symptom:"恢复一个个人提示词 后列表可能出现两份同 ID 记录。",root:'restoreTrashedPrompt 先 push，随后调用内部也 push 的 addImportedRecord，造成同一次恢复重复入库。',fix:'恢复只调用共用新增入口，保留来源、版本和状态；导入保存期间同样暂缓恢复，避免并发写入。',verify:'完整应用 DOM 回归执行归档、移入回收站、恢复再启用，检查同 ID 只保留一条，其他记录与后续批量导入正常；数据库重载顺序和版本保留回归通过。'});

