function copyText(text,btn,small){
  const done=()=>{ if(btn){ btn.classList.add('done'); const old=btn.textContent; btn.textContent='✓ 已复制'; setTimeout(()=>{btn.classList.remove('done');btn.textContent=old;},1600); }
    const t=$('#toast'); t.textContent=small?'✓ 摘录已复制到剪贴板':L('toast');
    t.classList.add('show'); clearTimeout(window.__tt); window.__tt=setTimeout(()=>t.classList.remove('show'),1900); };
  if(navigator.clipboard&&navigator.clipboard.writeText) navigator.clipboard.writeText(text).then(done).catch(()=>fallbackCopy(text,done));
  else fallbackCopy(text,done);
}
function fallbackCopy(text,done){
  const ta=document.createElement('textarea'); ta.value=text; ta.style.cssText='position:fixed;opacity:0';
  document.body.appendChild(ta); ta.select();
  try{ document.execCommand('copy'); done(); }catch(e){}
  document.body.removeChild(ta);
}
function mdLite(s){
  let out=esc(s);
  out=out.replace(/\*\*(.+?)\*\*/g,'<b style="color:var(--tx)">$1</b>');
  out=out.replace(/`([^`]+)`/g,'<code style="background:color-mix(in srgb,var(--tx) 10%,transparent);padding:1px 5px;border-radius:4px;font-size:12px">$1</code>');
  out=out.split('\n').filter(l=>l.trim()).map(l=>l.trim().replace(/^[-•]\s*/,'· ')).join('<br>');
  return out;
}

